package com.idiots3.riskscanner.model

/**
 * Security recommendation generated by RecommendationEngine.
 * Each actionable recommendation maps directly to an app detail view or system settings screen.
 */
enum class RecommendationPriority(val label: String, val weight: Int) {
    CRITICAL("Critical", 3),
    HIGH("High", 2),
    MEDIUM("Medium", 1),
    INFO("Info", 0)
}

enum class RecommendationAction {
    OPEN_APP_DETAIL,
    OPEN_APP_SETTINGS,
    OPEN_ACCESSIBILITY_SETTINGS,
    OPEN_DEVICE_ADMIN_SETTINGS,
    OPEN_NOTIFICATION_SETTINGS,
    OPEN_OVERLAY_SETTINGS,
    OPEN_INSTALL_APPS_SETTINGS,
    OPEN_SECURITY_SETTINGS,
    OPEN_DEVELOPER_SETTINGS,
    OPEN_SYSTEM_UPDATE,
    OPEN_CREDENTIAL_SETTINGS,
    OPEN_NETWORK_SETTINGS,
    OPEN_USAGE_ACCESS_SETTINGS,
    OPEN_LOCK_SCREEN_SETTINGS,
    OPEN_DISPLAY_SETTINGS,
    OPEN_VPN_SETTINGS,
    OPEN_PRIVATE_DNS_SETTINGS,
    OPEN_DEFAULT_APPS_SETTINGS,
    OPEN_INPUT_METHOD_SETTINGS,
    OPEN_AUTOFILL_SETTINGS,
    OPEN_APK_SCANNER,
    NONE
}

data class SecurityRecommendation(
    val id: String,
    val priority: RecommendationPriority,
    val title: String,
    val description: String,
    val action: RecommendationAction = RecommendationAction.NONE,
    val actionLabel: String? = null,
    val targetPackage: String? = null,
    val category: String
)

data class RecommendationSummary(
    val recommendations: List<SecurityRecommendation>,
    val deviceScore: Int,
    val scoreBreakdown: Map<String, Int>,
    val behaviourIncluded: Boolean = false
) {
    val criticalCount: Int get() = recommendations.count { it.priority == RecommendationPriority.CRITICAL }
    val highCount: Int get() = recommendations.count { it.priority == RecommendationPriority.HIGH }
    val totalActionable: Int get() = recommendations.count { it.action != RecommendationAction.NONE }
}
